//! Differential probe battery for the mpz port.
//!
//! Reads `scripts/mpz_vectors.txt` (generated by
//! `scripts/gen_mpz_vectors.py` from a CPython oracle, with explicit
//! mpz-semantics models where mpz.c differs from CPython — see the
//! generator header) and checks every case against the Rust port.
//! One case per line, space-separated: `op arg... expected...`.
//! All failures are collected and reported at the end, so one bad
//! case does not hide the rest.

use crate::vendor::mpz::bi;
use crate::vendor::mpz::BigInt;
use crate::vendor::mpz_ops;

const VECTORS: &str = include_str!("../../scripts/mpz_vectors.txt");

fn parse(s: &str) -> BigInt {
    bi(s)
}

fn parse_f(s: &str) -> f64 {
    // The generator emits repr(f) for floats: "inf", "-inf", "nan",
    // or a decimal literal. Rust's f64::from_str accepts "inf",
    // "-inf", "NaN" (capital N) but not "nan"; normalize.
    match s {
        "nan" => f64::NAN,
        "inf" => f64::INFINITY,
        "-inf" => f64::NEG_INFINITY,
        other => other.parse::<f64>().unwrap(),
    }
}

#[test]
fn probe_vectors() {
    let mut failures: Vec<String> = Vec::new();
    let mut count = 0usize;

    for (lineno, line) in VECTORS.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        count += 1;
        let f: Vec<&str> = line.split(' ').collect();
        let op = f[0];
        // Each arm checks one case and pushes a message on mismatch.
        let check = |got: String, want: &str, failures: &mut Vec<String>| {
            if got != want {
                failures.push(format!("line {}: {}: got {} want {}", lineno + 1, line, got, want));
            }
        };
        match op {
            "add" => {
                let r = parse(f[1]) + parse(f[2]);
                check(r.to_string(), f[3], &mut failures);
            }
            "sub" => {
                let r = parse(f[1]) - parse(f[2]);
                check(r.to_string(), f[3], &mut failures);
            }
            "mul" => {
                let r = parse(f[1]) * parse(f[2]);
                check(r.to_string(), f[3], &mut failures);
            }
            "divmod" => {
                let (q, r) = parse(f[1]).divmod(&parse(f[2])).unwrap();
                check(format!("{} {}", q, r), &format!("{} {}", f[3], f[4]), &mut failures);
            }
            "pow" => {
                let r = parse(f[1]).pow(&parse(f[2]));
                check(r.to_string(), f[3], &mut failures);
            }
            "pow3" => {
                let r = parse(f[1]).pow3(&parse(f[2]), &parse(f[3])).unwrap();
                check(r.to_string(), f[4], &mut failures);
            }
            "shl" => {
                let r = parse(f[1]) << f[2].parse::<u64>().unwrap();
                check(r.to_string(), f[3], &mut failures);
            }
            "shr" => {
                let r = parse(f[1]) >> f[2].parse::<u64>().unwrap();
                check(r.to_string(), f[3], &mut failures);
            }
            "and" => {
                let r = parse(f[1]) & parse(f[2]);
                check(r.to_string(), f[3], &mut failures);
            }
            "or" => {
                let r = parse(f[1]) | parse(f[2]);
                check(r.to_string(), f[3], &mut failures);
            }
            "xor" => {
                let r = parse(f[1]) ^ parse(f[2]);
                check(r.to_string(), f[3], &mut failures);
            }
            "neg" => {
                let r = -parse(f[1]);
                check(r.to_string(), f[2], &mut failures);
            }
            "not" => {
                let r = !parse(f[1]);
                check(r.to_string(), f[2], &mut failures);
            }
            "abs" => {
                let r = parse(f[1]).abs();
                check(r.to_string(), f[2], &mut failures);
            }
            "cmp" => {
                let r = parse(f[1]).cmp_mpz(&parse(f[2]));
                let got = match r {
                    std::cmp::Ordering::Less => "-1",
                    std::cmp::Ordering::Equal => "0",
                    std::cmp::Ordering::Greater => "1",
                };
                check(got.to_string(), f[3], &mut failures);
            }
            "bitlen" => {
                let r = parse(f[1]).bit_length();
                check(r.to_string(), f[2], &mut failures);
            }
            "fromstr" => {
                // f[1] is the literal ("_" stands for the empty string),
                // f[2] base, f[3] neg, f[4] consumed digits,
                // f[5] value, f[6] neg flag.
                let s = if f[1] == "_" { "" } else { f[1] };
                let base = f[2].parse::<u32>().unwrap();
                let neg = f[3] == "1";
                let mut z = BigInt::zero();
                let consumed = z.set_from_str(s.as_bytes(), neg, base);
                // Compare the value AND the sign flag separately:
                // set_from_str produces a "negative zero" (neg=true,
                // len=0) for "-0" and for "" with neg=true, exactly
                // like the C (which sets z->neg before parsing).
                // cmp-based PartialEq says -0 != 0, so a plain
                // value comparison would reject the faithful state.
                let want_neg = f[6] == "1";
                if consumed != f[4].parse::<usize>().unwrap()
                    || z.to_string() != f[5]
                    || z.is_neg() != want_neg
                {
                    failures.push(format!(
                        "line {}: {}: got consumed={} value={} neg={} want consumed={} value={} neg={}",
                        lineno + 1,
                        line,
                        consumed,
                        z,
                        z.is_neg(),
                        f[4],
                        f[5],
                        want_neg
                    ));
                }
            }
            "tostr" => {
                let r = parse(f[1]).as_str(f[2].parse::<u32>().unwrap(), "", b'a', 0);
                check(r, f[3], &mut failures);
            }
            "tostr_comma" => {
                let r = parse(f[1]).as_str(f[2].parse::<u32>().unwrap(), "", b'a', b',');
                check(r, f[3], &mut failures);
            }
            "frombytes" => {
                // f[1] hex, f[2] big_endian flag, f[3] value.
                let hex = f[1];
                let mut bytes = Vec::with_capacity(hex.len() / 2);
                let mut i = 0;
                while i < hex.len() {
                    bytes.push(u8::from_str_radix(&hex[i..i + 2], 16).unwrap());
                    i += 2;
                }
                let mut z = BigInt::zero();
                z.set_from_bytes(f[2] == "1", &bytes);
                check(z.to_string(), f[3], &mut failures);
            }
            "tobytes" => {
                // f[1] value, f[2] big_endian, f[3] as_signed,
                // f[4] length, f[5] hex ("-" if empty), f[6] ok flag.
                let v = parse(f[1]);
                let length = f[4].parse::<usize>().unwrap();
                let mut bytes = vec![0u8; length];
                let ok = v.as_bytes(f[2] == "1", f[3] == "1", &mut bytes);
                let got_hex = if bytes.is_empty() {
                    "-".to_string()
                } else {
                    bytes.iter().map(|b| format!("{:02x}", b)).collect()
                };
                if got_hex != f[5] || ok != (f[6] == "1") {
                    failures.push(format!(
                        "line {}: {}: got hex={} ok={} want hex={} ok={}",
                        lineno + 1,
                        line,
                        got_hex,
                        ok,
                        f[5],
                        f[6]
                    ));
                }
            }
            "hash" => {
                let h = parse(f[1]).hash_mpz();
                check(h.to_string(), f[2], &mut failures);
            }
            "asint" => {
                let got = parse(f[1]).as_int_checked();
                let want_ok = f[2] == "1";
                match got {
                    Some(v) => {
                        if !want_ok || v.to_string() != f[3] {
                            failures.push(format!(
                                "line {}: {}: got Some({}) want ok={} value={}",
                                lineno + 1,
                                line,
                                v,
                                want_ok,
                                f[3]
                            ));
                        }
                    }
                    None => {
                        if want_ok {
                            failures.push(format!(
                                "line {}: {}: got None want Some({})",
                                lineno + 1,
                                line,
                                f[3]
                            ));
                        }
                    }
                }
            }
            "asuint" => {
                let got = parse(f[1]).as_uint_checked();
                let want_ok = f[2] == "1";
                match got {
                    Some(v) => {
                        if !want_ok || v.to_string() != f[3] {
                            failures.push(format!(
                                "line {}: {}: got Some({}) want ok={} value={}",
                                lineno + 1,
                                line,
                                v,
                                want_ok,
                                f[3]
                            ));
                        }
                    }
                    None => {
                        if want_ok {
                            failures.push(format!(
                                "line {}: {}: got None want Some({})",
                                lineno + 1,
                                line,
                                f[3]
                            ));
                        }
                    }
                }
            }
            "fromfloat" => {
                let mut z = BigInt::zero();
                z.set_from_float(parse_f(f[1]));
                check(z.to_string(), f[2], &mut failures);
            }
            "asfloat" => {
                let got = parse(f[1]).as_float();
                let want = parse_f(f[2]);
                // Bit-exact float comparison (NaN never expected here).
                if got.to_bits() != want.to_bits() {
                    failures.push(format!(
                        "line {}: {}: got {} (bits {:#x}) want {} (bits {:#x})",
                        lineno + 1,
                        line,
                        got,
                        got.to_bits(),
                        want,
                        want.to_bits()
                    ));
                }
            }
            _ => {
                failures.push(format!("line {}: unknown op {:?}", lineno + 1, op));
            }
        }
        // Keep the ops module linked: exercise the free *_inpl entry
        // points on a sample of cases (behaviour identical to the
        // methods above; this guards the public free-function API).
        let _ = mpz_ops::add_inpl;
        let _ = mpz_ops::divmod_inpl;
    }

    assert!(
        failures.is_empty(),
        "{} probe case(s) run, {} failure(s):\n{}",
        count,
        failures.len(),
        failures.join("\n")
    );
    // Reaching here means every case passed; report the count in the
    // test output (visible with --nocapture).
    println!("probe battery: {} cases, 0 failures", count);
}
